#########################################################################
# Manual Edit 01
# Auto-detection of local or SciLifeLab app launching.
# Every instance of "merged_objassay_" or "immune_objassay_" must be 
# replaced by the variables merged_h5 or immune_h5 manually.
#########################################################################


#### auto-detect environment (this was updated by Emma Bolech after the script was generated by "makeShinyAppV4.R") ####
data_path <- if (file.exists("./merged_objconf.rds")) {
  "./"
} else if (file.exists("/srv/shiny-server/data/merged_objconf.rds")) {
  "/srv/shiny-server/data/"
} else {
  stop("Data not found in either local or mounted path")
}

#### also updated by Emma Bolech (every insance of the auto generated "merged_objassay_" in the script was replaced with the variable merged_h5 and same for "immune_objassay_" to immune_h5) ####
merged_h5 <- paste0(data_path, "merged_objassay_")  
immune_h5 <- paste0(data_path, "immune_objassay_")

#### the file paths here were updated by Emma Bolech after the script was generated ####
merged_objconf = readRDS(paste0(data_path, "merged_objconf.rds"))
merged_objmeta = readRDS(paste0(data_path, "merged_objmeta.rds"))
merged_objgene = readRDS(paste0(data_path,"merged_objgene.rds"))
merged_objdimr = readRDS(paste0(data_path,"merged_objdimr.rds"))
merged_objdef  = readRDS(paste0(data_path,"merged_objdef.rds"))
immune_objconf = readRDS(paste0(data_path,"immune_objconf.rds"))
immune_objmeta = readRDS(paste0(data_path,"immune_objmeta.rds"))
immune_objgene = readRDS(paste0(data_path,"immune_objgene.rds"))
immune_objdimr = readRDS(paste0(data_path,"immune_objdimr.rds"))
immune_objdef  = readRDS(paste0(data_path,"immune_objdef.rds"))
source("./shinyFunc.R")
pdf(file = NULL)

