names(sList) = c("Small", "Medium", "Large") 



### Start server code 
shinyServer(function(input, output, session) { 
  ### For all tags and Server-side selectize 
  observe_helpers() 
  optCrt="{ option_create: function(data,escape) {return('<div class=\"create\"><strong>' + '</strong></div>');} }" 
  observe({ 
    invalidateLater(30000) # ping every 30 seconds to keep connection alive 
    cat(".") 
  }) 

### Functions for tab A1 
getGmerged_obja1inp1 <- reactive({ 
  req(gsub("^Assay: ", "", input$merged_obja1ass1)) 
  if(gsub("^Assay: ", "", input$merged_obja1ass1) == "Cell Information"){ 
    res <- merged_objconf$UI 
    resDef <- merged_objdef$meta1 
    resLen <- length(res) 
  } else { 
    res <- names(merged_objgene[[gsub("^Assay: ", "", input$merged_obja1ass1)]]) 
    resDef <- merged_objdef$gene1[[gsub("^Assay: ", "", input$merged_obja1ass1)]] 
    resLen <- 7 
  } 
  return(list(res,resDef,resLen))
})
observeEvent(gsub("^Assay: ", "", input$merged_obja1ass1), {
  updateSelectizeInput(session, "merged_obja1inp1", choices = getGmerged_obja1inp1()[[1]], 
                       server = TRUE, selected = getGmerged_obja1inp1()[[2]], options = list( 
                         maxOptions = getGmerged_obja1inp1()[[3]], create = TRUE, 
                         persist = TRUE, render = I(optCrt))) 
})
output$merged_obja1sub1.ui <- renderUI({ 
  sub = strsplit(merged_objconf[UI == input$merged_obja1sub1]$fID, "\\|")[[1]] 
  checkboxGroupInput("merged_obja1sub2", "Select which cells to show", inline = TRUE, 
                     choices = sub, selected = sub) 
}) 
observeEvent(input$merged_obja1sub1non, { 
  sub = strsplit(merged_objconf[UI == input$merged_obja1sub1]$fID, "\\|")[[1]] 
  updateCheckboxGroupInput(session, inputId = "merged_obja1sub2", label = "Select which cells to show", 
                           choices = sub, selected = NULL, inline = TRUE) 
}) 
observeEvent(input$merged_obja1sub1all, { 
  sub = strsplit(merged_objconf[UI == input$merged_obja1sub1]$fID, "\\|")[[1]] 
  updateCheckboxGroupInput(session, inputId = "merged_obja1sub2", label = "Select which cells to show", 
                           choices = sub, selected = sub, inline = TRUE) 
}) 

merged_obja1oup1xy <- reactiveValues(x = NULL, y = NULL)
observe({
  brush <- input$merged_obja1inp1.br
  if (!is.null(brush)) {
    merged_obja1oup1xy$x <- c(brush$xmin, brush$xmax)
    merged_obja1oup1xy$y <- c(brush$ymin, brush$ymax)
  } else {
    merged_obja1oup1xy$x <- NULL; merged_obja1oup1xy$y <- NULL
  }
})
merged_obja1oup1br <- reactive({
  sc2Ddimr(merged_objconf, merged_objmeta, merged_objdimr, input$merged_obja1dr, input$merged_obja1inp1,
           merged_h5, merged_objgene, input$merged_obja1ass1, input$merged_obja1sub1, input$merged_obja1sub2,  
           input$merged_obja1min1, input$merged_obja1max1, input$merged_obja1siz/2, input$merged_obja1ord1,
           cList[[input$merged_obja1col1]], sList[input$merged_obja1fsz]/2, 
           input$merged_obja1asp, FALSE, FALSE) 
})
output$merged_obja1oup1.br <- renderPlot({merged_obja1oup1br() + theme(legend.position = "none")}) 

merged_obja1oup1 <- reactive({
  sc2Ddimr(merged_objconf, merged_objmeta, merged_objdimr, input$merged_obja1dr, input$merged_obja1inp1,
           merged_h5, merged_objgene, input$merged_obja1ass1, input$merged_obja1sub1, input$merged_obja1sub2,  
           input$merged_obja1min1, input$merged_obja1max1, input$merged_obja1siz, input$merged_obja1ord1,
           cList[[input$merged_obja1col1]], sList[input$merged_obja1fsz], 
           input$merged_obja1asp, input$merged_obja1txt, input$merged_obja1lab1)
})
output$merged_obja1oup1 <- renderPlot({
  if(is.null(merged_obja1oup1xy$x[1])){
    merged_obja1oup1() + theme(legend.position = "none")
  } else {
    merged_obja1oup1() + theme(legend.position = "none") + 
      scale_x_continuous(limits = merged_obja1oup1xy$x, expand = c(0, 0)) + 
      scale_y_continuous(limits = merged_obja1oup1xy$y, expand = c(0, 0)) 
  }
})
output$merged_obja1oup1.ui <- renderUI({plotOutput("merged_obja1oup1", height = pList[input$merged_obja1psz])})
output$merged_obja1oup1.dl <- downloadHandler(
  filename = function() { paste0("merged_obj",input$merged_obja1dr,"_",input$merged_obja1inp1,".",input$merged_obja1oup1.f) },
  content = function(file) { 
    if(is.null(merged_obja1oup1xy$x[1])){
      ggsav(file, height = input$merged_obja1oup1.h, width = input$merged_obja1oup1.w, 
            plot = merged_obja1oup1() + theme(legend.position = "none"))
    } else {
      ggsav(file, height = input$merged_obja1oup1.h, width = input$merged_obja1oup1.w, 
            plot = merged_obja1oup1() + theme(legend.position = "none") + 
              scale_x_continuous(limits = merged_obja1oup1xy$x, expand = c(0, 0)) + 
              scale_y_continuous(limits = merged_obja1oup1xy$y, expand = c(0, 0)))
    }
})
output$merged_obja1oup3 <- renderPlot({grid.newpage(); grid.draw(g_legend(merged_obja1oup1()))})
output$merged_obja1oup3.ui <- renderUI({plotOutput("merged_obja1oup3", height = 72*convertHeight(
  grobHeight(g_legend(merged_obja1oup1())), unitTo="in", valueOnly=TRUE) + 50)})
output$merged_obja1oup3.dl <- downloadHandler(
  filename = function() { paste0("merged_obj",input$merged_obja1dr,"_",input$merged_obja1inp1,"_leg.",input$merged_obja1oup3.f) },
  content = function(file) { 
    grid.newpage(); grid.draw(g_legend(merged_obja1oup1()))
    ggsav(file, height = input$merged_obja1oup3.h, width = input$merged_obja1oup3.w, plot = grid.grab())
}) 

output$merged_obja1.dt <- renderDataTable({
  ggData = sc2Dnum(merged_objconf, merged_objmeta, merged_objdimr, input$merged_obja1dr, merged_obja1oup1xy$x, merged_obja1oup1xy$y, input$merged_obja1inp1,
                   merged_h5, merged_objgene, input$merged_obja1ass1, input$merged_obja1sub1, input$merged_obja1sub2, input$merged_obja1splt)
  datatable(ggData, rownames = FALSE, extensions = "Buttons",
            options = list(pageLength = -1, dom = "tB", buttons = c("copy", "csv", "excel"))) %>%
    formatRound(columns = c("pctZoom"), digits = 2)
})


