getGmerged_objb1inp1 <- reactive({ 
  req(gsub("^Assay: ", "", input$merged_objb1ass1)) 
  if(gsub("^Assay: ", "", input$merged_objb1ass1) == "Cell Information"){ 
    res <- merged_objconf[is.na(fID)]$UI 
    resDef <- merged_objconf[is.na(fID)]$UI[1] 
    resLen <- length(res) 
