#########################################################################
# Manual Edit 02
# Cell Type Mode addition to heatmap/bubblepot. 
# Allows users to plot gene expression across batch/sample_id/timepoint
# for one selected celltype. 
#########################################################################

merged_objb3oup <- reactive({
  # this section was added to support switched between the default subsetting and the cell type mode
  if (input$merged_objb3_use_celltype) {   
    sub1 <- "annotated_celltype"                # subset by cell type annotation
    sub2 <- c(input$merged_objb3_celltype)      # selected cell type
    grp  <- input$merged_objb3_celltype_grp     # group by chosen variable
    scl  <- input$merged_objb3scl               # apply scaling if selected
  # otherwise do default subsetting
  } else {
    sub1 <- input$merged_objb3sub1
    sub2 <- input$merged_objb3sub2
    grp  <- input$merged_objb3grp
    scl  <- input$merged_objb3scl
  }

  # this section was added to catch and rename the error in cell type mode when not enough cell information is present
  # this prompts the user to try and remove the gene expression scaling
  tryCatch({

  scBubbHeat(merged_objconf, merged_objmeta, input$merged_objb3inp,
             grp, input$merged_objb3plt,
             paste0(merged_h5, input$merged_objb3ass1, ".h5"),
             merged_objgene[[input$merged_objb3ass1]],
             sub1, sub2, scl,
             input$merged_objb3row, input$merged_objb3col,
             cList[[input$merged_objb3cols]], sList[input$merged_objb3fsz],
             input$merged_objb3exp, input$merged_objb3max)
  
  # error catching as described above
  }, error = function(e) {
    if (grepl("NA/NaN/Inf", e$message)) {
      stop("Not enough cell information — try removing scaled expression or check for low-variance genes.")
    } else {
      stop(e)
    }
  }) 
})

  
#########################################################################
#########################################################################

  
  
